-- =============================================================================
-- Step 6D / 38 - JSON index experiment: state and result verification for one phase (read-only)
-- =============================================================================
-- GENERATED by scripts/step6d_json_index_experiment.py - do not edit by hand.
--   psql -X -v ON_ERROR_STOP=1 -v phase=<I-0|I-1|I-2|I-3|final> -d postgresql_regex_task -f sql/38_verify_json_index_phase.sql
--
-- READ ONLY transaction, rolled back. Exits non-zero (SQLSTATE LR015) unless every check passes:
--   G-01 .. G-08  both tables 5,000 rows; documents unchanged (canonical md5, json::jsonb = jsonb); index set = the
--                 phase design; every index valid, ready and live; no row inserted, updated or deleted; heap pages
--   G-09          access method and operator class of every experiment index
--   G-10          the five btree expression index definitions are identical on json and jsonb (table names normalised)
--   R-...         result checksum of every phase statement = access_log_flat oracle, with default settings and again
--                 with enable_seqscan off (phases with indexes)
-- =============================================================================

\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
\pset footer off

\if :{?phase}
\else
    \echo 'pass -v phase=I-0|I-1|I-2|I-3|final'
    DO $$ BEGIN RAISE EXCEPTION 'missing or unknown psql variable; see the header of this file'; END $$;
\endif

SELECT :'phase' = 'I-0' AS is_i0, :'phase' = 'I-1' AS is_i1, :'phase' = 'I-2' AS is_i2, :'phase' = 'I-3' AS is_i3, :'phase' = 'final' AS is_final \gset

BEGIN TRANSACTION READ ONLY;

SET LOCAL TimeZone = 'UTC';

\echo '== Indexes on the experiment tables'
SELECT c.relname AS table_name, ic.relname AS index_name, am.amname AS method, i.indisvalid AS valid, i.indisready AS ready,
       i.indislive AS live, pg_relation_size(ic.oid) AS size_bytes, ic.relpages AS pages, ic.reltuples::bigint AS reltuples,
       pg_get_indexdef(ic.oid) AS definition
FROM pg_index i
JOIN pg_class ic ON ic.oid = i.indexrelid
JOIN pg_class c  ON c.oid = i.indrelid
JOIN pg_am am    ON am.oid = ic.relam
WHERE c.relnamespace = 'log_regex_json'::regnamespace
ORDER BY c.relname, ic.relname;

\if :is_i0
\echo '== Phase I-0: no secondary index (control, before any index)'
DO $verify$
DECLARE
    v_failed text[] := '{}';
    v_checks integer := 0;
    chk      record;
BEGIN
    FOR chk IN
        SELECT c.id, c.name, c.expected, c.actual
        FROM (VALUES
                ('G-01', 'access_log_json rows', '5000', (SELECT count(*)::text FROM log_regex_json.access_log_json)),
                ('G-02', 'access_log_jsonb rows', '5000', (SELECT count(*)::text FROM log_regex_json.access_log_jsonb)),
                ('G-03', 'md5 of json document texts = canonical input md5 recorded at load (documents unchanged)', (SELECT substring(obj_description('log_regex_json.access_log_json'::regclass, 'pg_class') FROM 'md5 ([0-9a-f]{32})')), (SELECT md5(string_agg(doc::text, chr(10) ORDER BY log_id)) FROM log_regex_json.access_log_json)),
                ('G-04', 'jsonb documents = json documents cast to jsonb (documents unchanged)', '5000', (SELECT count(*)::text FROM log_regex_json.access_log_json j JOIN log_regex_json.access_log_jsonb b ON b.log_id = j.log_id WHERE j.doc::jsonb = b.doc)),
                ('G-05', 'indexes on the experiment tables = phase I-0 design', 'access_log_json_pkey,access_log_jsonb_pkey', (SELECT string_agg(ic.relname, ',' ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid JOIN pg_class c ON c.oid = i.indrelid WHERE c.relnamespace = 'log_regex_json'::regnamespace)),
                ('G-06', 'indexes that are not valid, not ready or not live', '0', (SELECT count(*)::text FROM pg_index i JOIN pg_class c ON c.oid = i.indrelid WHERE c.relnamespace = 'log_regex_json'::regnamespace AND NOT (i.indisvalid AND i.indisready AND i.indislive))),
                ('G-07', 'rows inserted / updated / deleted since creation (json, jsonb)', '5000/0/0 5000/0/0', (SELECT string_agg(s.n_tup_ins || '/' || (s.n_tup_upd + s.n_tup_hot_upd) || '/' || s.n_tup_del, ' ' ORDER BY s.relname) FROM pg_stat_user_tables s WHERE s.schemaname = 'log_regex_json')),
                ('G-08', 'heap pages (json / jsonb) as measured in Step 6B', '1250/981', (SELECT (SELECT relpages FROM pg_class WHERE oid = 'log_regex_json.access_log_json'::regclass) || '/' || (SELECT relpages FROM pg_class WHERE oid = 'log_regex_json.access_log_jsonb'::regclass))),
                ('R-Q07-json', 'Q07 json result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex.access_log_flat WHERE record_validity = 'BROKEN') AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex_json.access_log_json WHERE doc->'record'->>'record_validity' = 'BROKEN') AS r) AS s)),
