                ('R-Q10-json', 'Q10 json result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex.access_log_flat WHERE status_code = 404) AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex_json.access_log_json WHERE (doc->'fields'->'status'->>'code')::integer = 404) AS r) AS s)),
