                ('R-C2-jsonb', 'C2 jsonb result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex.access_log_flat WHERE diagnostics @> ARRAY['truncated']) AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex_json.access_log_jsonb WHERE doc->'record'->'diagnostics' ? 'truncated') AS r) AS s)),
