        v_checks := v_checks + 1;
        IF chk.expected IS NOT DISTINCT FROM chk.actual THEN
            RAISE NOTICE '% PASS  %: %', chk.id, chk.name, chk.actual;
        ELSE
            v_failed := v_failed || chk.id;
            RAISE WARNING '% FAIL  %: expected %, actual %', chk.id, chk.name, chk.expected, chk.actual;
        END IF;
    END LOOP;

    IF cardinality(v_failed) > 0 THEN
        RAISE EXCEPTION 'JSON index phase I-0 check FAILED: % of % checks: %', cardinality(v_failed), v_checks, array_to_string(v_failed, ', ')
            USING ERRCODE = 'LR015';
    END IF;
    RAISE NOTICE 'JSON index phase I-0 check PASSED: all % checks', v_checks;
END
$verify$;
\elif :is_i1
\echo '== Phase I-1: identical btree expression indexes on both tables'
DO $verify$
DECLARE
    v_failed text[] := '{}';
    v_checks integer := 0;
    chk      record;
BEGIN
    FOR chk IN
        SELECT c.id, c.name, c.expected, c.actual
