                ('R-Q12b-jsonb', 'Q12b jsonb result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex.access_log_flat WHERE event_timestamp_utc >= '2026-03-01 00:00:00+00' AND event_timestamp_utc < '2026-03-08 00:00:00+00') AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex_json.access_log_jsonb WHERE doc->'fields'->'event_timestamp'->>'utc' >= '2026-03-01T00:00:00.000000Z' AND doc->'fields'->'event_timestamp'->>'utc' < '2026-03-08T00:00:00.000000Z') AS r) AS s)),
                ('R-Q12c-json', 'Q12c json result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex.access_log_flat WHERE event_timestamp_utc >= '2026-03-01 00:00:00+00' AND event_timestamp_utc < '2026-04-01 00:00:00+00') AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex_json.access_log_json WHERE doc->'fields'->'event_timestamp'->>'utc' >= '2026-03-01T00:00:00.000000Z' AND doc->'fields'->'event_timestamp'->>'utc' < '2026-04-01T00:00:00.000000Z') AS r) AS s)),
