                ('R-Q17-json', 'Q17 json result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT entity_type_code AS code, count(*) AS n FROM log_regex.access_log_flat GROUP BY 1) AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT doc->'fields'->'entity_type'->>'code' AS code, count(*) AS n FROM log_regex_json.access_log_json GROUP BY 1) AS r) AS s)),
                ('R-Q17-jsonb', 'Q17 jsonb result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT entity_type_code AS code, count(*) AS n FROM log_regex.access_log_flat GROUP BY 1) AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT doc->'fields'->'entity_type'->>'code' AS code, count(*) AS n FROM log_regex_json.access_log_jsonb GROUP BY 1) AS r) AS s)),
                ('R-Q09-json', 'Q09 json result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex.access_log_flat WHERE format_family = 'F1') AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex_json.access_log_json WHERE doc->'record'->>'format_family' = 'F1') AS r) AS s)),
                ('R-Q09-jsonb', 'Q09 jsonb result = access_log_flat oracle', (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex.access_log_flat WHERE format_family = 'F1') AS r) AS s), (SELECT count(*) || ':' || coalesce(md5(string_agg(s.x, chr(10) ORDER BY s.x)), '-') FROM (SELECT r::text AS x FROM (SELECT log_id FROM log_regex_json.access_log_jsonb WHERE doc->'record'->>'format_family' = 'F1') AS r) AS s))
