                ('G-07', 'rows inserted / updated / deleted since creation (json, jsonb)', '5000/0/0 5000/0/0', (SELECT string_agg(s.n_tup_ins || '/' || (s.n_tup_upd + s.n_tup_hot_upd) || '/' || s.n_tup_del, ' ' ORDER BY s.relname) FROM pg_stat_user_tables s WHERE s.schemaname = 'log_regex_json')),
                ('G-08', 'heap pages (json / jsonb) as measured in Step 6B', '1250/981', (SELECT (SELECT relpages FROM pg_class WHERE oid = 'log_regex_json.access_log_json'::regclass) || '/' || (SELECT relpages FROM pg_class WHERE oid = 'log_regex_json.access_log_jsonb'::regclass))),
                ('G-09', 'access method and operator class of every experiment index', 'access_log_json_i1a_record_validity:btree:text_ops,access_log_json_i1b_entity_type_code:btree:text_ops,access_log_json_i1c_status_code:btree:int4_ops,access_log_json_i1d_latitude_degrees:btree:numeric_ops,access_log_json_i1e_event_timestamp_utc:btree:text_ops,access_log_jsonb_i1a_record_validity:btree:text_ops,access_log_jsonb_i1b_entity_type_code:btree:text_ops,access_log_jsonb_i1c_status_code:btree:int4_ops,access_log_jsonb_i1d_latitude_degrees:btree:numeric_ops,access_log_jsonb_i1e_event_timestamp_utc:btree:text_ops,access_log_jsonb_i2_gin_jsonb_ops:gin:jsonb_ops', (SELECT string_agg(ic.relname || ':' || am.amname || ':' || opc.opcname, ',' ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid JOIN pg_class c ON c.oid = i.indrelid JOIN pg_am am ON am.oid = ic.relam JOIN pg_opclass opc ON opc.oid = i.indclass[0] WHERE c.relnamespace = 'log_regex_json'::regnamespace AND NOT i.indisprimary)),
                ('G-10', 'btree expression index definitions identical on json and jsonb (table names normalised)', '5', (SELECT count(*)::text FROM (VALUES ('i1a_record_validity'), ('i1b_entity_type_code'), ('i1c_status_code'), ('i1d_latitude_degrees'), ('i1e_event_timestamp_utc')) AS s (suffix) WHERE regexp_replace(pg_get_indexdef(to_regclass('log_regex_json.access_log_json_' || s.suffix)), 'access_log_jsonb?', 'T', 'g') = regexp_replace(pg_get_indexdef(to_regclass('log_regex_json.access_log_jsonb_' || s.suffix)), 'access_log_jsonb?', 'T', 'g'))),
